   192	// and which files exist. Unlike determineSettingsTarget, this correctly handles
   193	// local-only repos by checking for settings.local.json when settings.json is absent.
   194	func settingsTargetFile(ctx context.Context, useLocal, useProject bool) (string, string) {
   195		if useLocal {
