   197		}
   198		if useProject {
   199			return settings.EntireSettingsFile, configDisplayProject
   200		}
   201	
   202		// No explicit flag — write to whichever file exists.
   203		// Check project file first, then local.
   204		projectAbs, err := paths.AbsPath(ctx, settings.EntireSettingsFile)
   205		if err == nil {
   206			if _, statErr := os.Stat(projectAbs); statErr == nil {
   207				return settings.EntireSettingsFile, configDisplayProject
   208			}
   209		}
   210		localAbs, err := paths.AbsPath(ctx, settings.EntireSettingsLocalFile)
   211		if err == nil {
   212			if _, statErr := os.Stat(localAbs); statErr == nil {
   213				return settings.EntireSettingsLocalFile, configDisplayLocal
   214			}
   215		}
   216	
   217		// Neither exists — default to project
   218		return settings.EntireSettingsFile, configDisplayProject
   219	}
